-- Question integrity sync, generated by scripts/build-db-sync.mjs from content/ (reviewed schedule from 2026-11-28).
-- 1. question metadata  2. guard on daily_sets  3. usage view  4. reviewed wording  5. reviewed schedule from 2026-11-28
begin;

alter table public.questions
  add column if not exists fact_id text,
  add column if not exists status text not null default 'active',
  add column if not exists status_reason text,
  add column if not exists reviewed_on date;
do $$ begin
  alter table public.questions add constraint questions_status_check check (status in ('active', 'quarantined', 'retired'));
exception when duplicate_object then null; end $$;
create index if not exists questions_fact_id_idx on public.questions (fact_id);

-- Every daily puzzle row is checked as it is written. Published days (up to UK today) can't be edited or deleted, and a
-- new day can't reuse a fact that any other day already used, or a quarantined question. An advisory lock serialises
-- concurrent writers, so two jobs scheduling at once can't both slip the same question in.
-- Controlled correction of a published day (see docs/content/RUNBOOK.md): set local dialin.correction = 'on' in the same transaction.
create or replace function public.guard_daily_sets() returns trigger
language plpgsql security definer set search_path = public as $fn$
declare bad text; correcting boolean := coalesce(current_setting('dialin.correction', true), '') = 'on';
begin
  perform pg_advisory_xact_lock(hashtext('public.daily_sets'));
  if tg_op in ('UPDATE', 'DELETE') and old.puzzle_date <= public.uk_today() and not correcting then
    raise exception 'Published puzzle % cannot be changed (use the correction procedure)', old.puzzle_date;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'INSERT' and new.puzzle_date < public.uk_today() and not correcting then
    raise exception 'Cannot add a puzzle for a past date (%)', new.puzzle_date;
  end if;
  if coalesce(array_length(new.question_ids, 1), 0) <> 7 or (select count(distinct x) from unnest(new.question_ids) x) <> 7 then
    raise exception 'A daily puzzle needs 7 different questions';
  end if;
  select string_agg(x, ', ') into bad from unnest(new.question_ids) x where not exists (select 1 from public.questions qq where qq.id = x and qq.status = 'active');
  if bad is not null then raise exception 'Not an active question: %', bad; end if;
  if (select count(distinct coalesce(qq.fact_id, qq.id)) from public.questions qq where qq.id = any(new.question_ids)) <> 7 then
    raise exception 'Two questions in this puzzle test the same fact';
  end if;
  if not correcting then
    select string_agg(distinct x, ', ') into bad
    from unnest(new.question_ids) x join public.questions qn on qn.id = x
    where exists (select 1 from public.daily_sets o cross join unnest(o.question_ids) y join public.questions qo on qo.id = y
                  where o.puzzle_date <> new.puzzle_date and coalesce(qo.fact_id, qo.id) = coalesce(qn.fact_id, qn.id));
    if bad is not null then raise exception 'Already used in another daily puzzle (same fact): %', bad; end if;
  end if;
  return new;
end $fn$;
revoke all on function public.guard_daily_sets() from public, anon, authenticated;
drop trigger if exists daily_sets_guard on public.daily_sets;

-- Where every question has been used (one row per question per puzzle). Not readable by players.
create or replace view public.question_usage with (security_invoker = true) as
  select qq.id as question_id, coalesce(qq.fact_id, qq.id) as fact_id, qq.category, qq.question, qq.answer, qq.unit, qq.source,
         qq.status, qq.reviewed_on, ds.puzzle_date, ds.puzzle_no, u.pos as position, ds.puzzle_date <= public.uk_today() as published
  from public.daily_sets ds cross join lateral unnest(ds.question_ids) with ordinality as u(qid, pos) join public.questions qq on qq.id = u.qid;
revoke all on public.question_usage from public, anon, authenticated;

update public.questions set reviewed_on = date '2026-11-26' where reviewed_on is null;
update public.questions qq set fact_id = v.f from (values ('g03','g03'),('lm33','g03'),('g42','g42'),('lm34','g42'),('x285','x285'),('y121','x285'),('x317','x317'),('y082','x317'),('fm06','fm06'),('y129','fm06'),('sc15','sc15'),('y063','sc15'),('p09','p09'),('p35','p09'),('p51','p51'),('y118','p51'),('x329','x329'),('y136','x329'),('x351','x351'),('y140','x351'),('x398','x398'),('y131','x398'),('lm15','lm15'),('y113','lm15'),('p22','p22'),('y122','p22'),('x379','x379'),('y127','x379'),('g62','g62'),('y103','g62'),('x185','x185'),('y107','x185'),('x362','x362'),('y128','x362'),('x133','x133'),('y137','x133'),('r02','r02'),('y033','r02'),('s52','s52'),('y138','s52'),('sp03','sp03'),('y119','sp03'),('b03','b03'),('y042','b03'),('c46','c46'),('y024','c46'),('x025','x025'),('y002','x025'),('x022','x022'),('y006','x022'),('b17','b17'),('y068','b17'),('x076','x076'),('y052','x076'),('x079','x079'),('y031','x079'),('sc05','sc05'),('y060','sc05'),('x393','x393'),('y130','x393'),('f10','f10'),('fd13','f10'),('u09','u09'),('y003','u09'),('h45','h45'),('z030','h45'),('x247','x247'),('x266','x247'),('h26','h26'),('z055','h26')) v(id, f) where qq.id = v.id and qq.fact_id is distinct from v.f;
update public.questions set status = 'quarantined', status_reason = 'Scottish jury size changes from 15 to 12 under the Victims, Witnesses, and Justice Reform (Scotland) Act 2025; answer depends on commencement date' where id = 'y049' and status <> 'quarantined';
update public.questions set status = 'quarantined', status_reason = 'The question gives the answer away (''the Jackson 5'')' where id = 'z245' and status <> 'quarantined';
update public.questions set question = 'In 2025, roughly how many people lived in the world, in billions?', explanation = 'About 8.2 billion (UN estimate for 2025). 8 to 8.3 counts as exact.' where id = 'x190' and question is distinct from 'In 2025, roughly how many people lived in the world, in billions?';
update public.questions set question = 'In 2025, roughly how many people lived in the USA, in millions?', explanation = 'About 340 million (US Census Bureau estimate for 2025). 335 to 345 counts as exact.' where id = 'x192' and question is distinct from 'In 2025, roughly how many people lived in the USA, in millions?';
update public.questions set question = 'By the end of 2025, how many European Cups / Champions League titles had Liverpool won?', explanation = '1977, 1978, 1981, 1984, 2005 and 2019.' where id = 'p47' and question is distinct from 'By the end of 2025, how many European Cups / Champions League titles had Liverpool won?';
update public.questions set question = 'By the end of 2025, how many Super Bowls had the New England Patriots won?', explanation = 'Six, tied with the Pittsburgh Steelers for the most. They lost Super Bowl LX in 2026 to Seattle.' where id = 'sp16' and question is distinct from 'By the end of 2025, how many Super Bowls had the New England Patriots won?';
update public.questions set question = 'In mid-2024, roughly how many people lived in the UK, in millions?', explanation = 'About 69.3 million (ONS mid-2024 estimate). 68.5 to 70 counts as exact.' where id = 'x189' and question is distinct from 'In mid-2024, roughly how many people lived in the UK, in millions?';
update public.questions set question = 'What was Usain Bolt’s time when he set the 100 m world record in 2009, in seconds?', explanation = '9.58 s, Berlin 2009.' where id = 'p41' and question is distinct from 'What was Usain Bolt’s time when he set the 100 m world record in 2009, in seconds?';
update public.questions set question = 'Mike Powell set the men’s long jump world record in 1991. How far did he jump, in metres?', explanation = 'Mike Powell, 1991.' where id = 'z127' and question is distinct from 'Mike Powell set the men’s long jump world record in 1991. How far did he jump, in metres?';
update public.questions set question = 'Florence Griffith-Joyner set the women’s 100 m world record in 1988. What was her time, in seconds?', explanation = 'Florence Griffith-Joyner, 1988.' where id = 'z128' and question is distinct from 'Florence Griffith-Joyner set the women’s 100 m world record in 1988. What was her time, in seconds?';
update public.questions set question = 'What was Usain Bolt’s time when he set the 200 m world record in 2009, in seconds?', explanation = 'Berlin, 2009.' where id = 'z129' and question is distinct from 'What was Usain Bolt’s time when he set the 200 m world record in 2009, in seconds?';
update public.questions set question = 'Javier Sotomayor set the men’s high jump world record in 1993. How high did he jump, in metres?', explanation = 'Javier Sotomayor, 1993.' where id = 'z130' and question is distinct from 'Javier Sotomayor set the men’s high jump world record in 1993. How high did he jump, in metres?';
delete from public.daily_sets where puzzle_date >= greatest(date '2026-11-28', public.uk_today() + 1);
create trigger daily_sets_guard before insert or update or delete on public.daily_sets for each row execute function public.guard_daily_sets();
) v(d, n, ids) where v.d::date > public.uk_today() on conflict (puzzle_date) do nothing;
commit;
